#!/usr/bin/env python3
"""Build one audited, dependency-free dashboard. Legacy artifacts stay in Git."""
import html, json
from pathlib import Path
R=Path(__file__).resolve().parent.parent; P=R/'pages'; P.mkdir(exist_ok=True)
def read(p): return json.loads((R/p).read_text())
s=read('data/audit-snapshot.json'); flags=read('data/flagged.json')['items']; src=read('data/sources.json')['sources']; inv=read('analysis/audit-inventory.json')['rows']; audit=read('analysis/repo-audit.json'); lines=read('analysis/model-lines-week9.json'); corr=read('analysis/correlations.json'); strategies=read('analysis/strategies.json')['strategies']; board=read('analysis/leaderboard.json'); gates=read('analysis/validation-gates.json')['gates']
def e(x): return html.escape(str(x)) if x is not None else ''
def a(u,label='Official source'): return f'<a href="{e(u)}" target="_blank" rel="noopener noreferrer">{e(label)} ↗</a>'
def b(t): return '<span class="badge '+('good' if t=='VERIFIED' else 'warn' if 'UNVERIFIED' in t or 'BLOCKED' in t else 'neutral')+'">'+e(t)+'</span>'
def table(headers,rows,caption):
 out='<div class="table-tools"><label>Filter rows <input type="search" placeholder="Search this table…" aria-label="Filter '+e(caption)+'"></label><span class="row-count">'+str(len(rows))+' rows</span></div><div class="table-wrap"><table><caption>'+e(caption)+'</caption><thead><tr>'+''.join('<th scope="col">'+e(h)+'</th>' for h in headers)+'</tr></thead><tbody>'
 for row in rows:
  out+='<tr>'+''.join('<td'+(' class="missing" aria-label="Unverified or not available"' if c is None else '')+'>'+('' if c is None else str(c) if isinstance(c,str) and c.startswith('<') else e(c))+'</td>' for c in row)+'</tr>'
 return out+'</tbody></table></div><p class="table-note">Empty cells are intentionally blank: unavailable or unverified. Links on unverified rows are verification targets, not proof.</p>'
NAV=[('index','Overview','01'),('executive-summary','Executive summary','02'),('standings','Team standings','03'),('schedule','Schedule & scores','04'),('model-lines','Line origination','05'),('strategies','Strategy library','06'),('correlations','Correlations','07'),('leaderboard','Skill leaderboard','08'),('validation-gates','Validation gates','09'),('injuries','Availability & news','10'),('player-stats','Data inventory','11'),('methodology','Methodology','12'),('repo-review','Repository audit','13'),('sources','Source register','14'),('flagged','Flagged for Review','15'),('responsible-gambling','Responsible research','16')]
def wrap(slug,title,desc,body):
 root=slug=='index'; pre='' if root else '../'
 nav=''.join(f'<a {"aria-current=page" if key==slug else ""} href="{pre+"index.html" if key=="index" else ("pages/" if root else "")+key+".html"}"><span>{n}</span>{label}</a>' for key,label,n in NAV)
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="description" content="{e(desc)}"><title>{e(title)} · Own8</title><link rel="stylesheet" href="{pre}assets/style.css"><script src="{pre}assets/app.js" defer></script></head><body><a class="skip" href="#main">Skip to content</a><aside><a class="brand" href="{pre}index.html"><span class="brand-mark">8</span> OWN8<span class="lab">RESEARCH LAB</span></a><div class="nav-label">NFL / RESEARCH WORKSPACE</div><nav aria-label="Main navigation">{nav}</nav><div class="aside-foot"><span class="pulse"></span> Official-source audit<br><small>Snapshot · 04 NOV 2026<br>Paper research only</small></div></aside><div class="workspace"><header><span>NFL LINE ORIGINATION <span class="muted">/ {e(title)}</span></span><span class="date">2026 SEASON · WEEK 09</span></header><main id="main"><div class="eyebrow">OWN8 INTELLIGENCE / {s['as_of']}</div><h1>{e(title)}</h1><p class="lead">{e(desc)}</p>{body}</main><footer><span>OWN8 · Evidence before edge.</span><span>Snapshot, not live odds. No wagering or cash rewards.</span></footer></div></body></html>'''
def page(slug,title,desc,body): (R/'index.html' if slug=='index' else P/(slug+'.html')).write_text(wrap(slug,title,desc,body))
def note(t): return '<div class="notice"><strong>Research boundary</strong><p>'+e(t)+'</p></div>'
def sec(t): return '<h2>'+e(t)+'</h2>'
# Overview
cards=[('32','Team records audited','standings'),('15','Illustrative game lines','model-lines'),('0','Eligible strategies','validation-gates'),(str(len(flags)),'Items for review','flagged')]
kpis='<div class="kpis">'+''.join(f'<a class="kpi" href="pages/{u}.html"><span>{n}</span><h2>{t}</h2><small>Explore findings ↗</small></a>' for n,t,u in cards)+'</div>'
hero='<div class="hero"><div><span class="pill">VERIFICATION-FIRST NFL RESEARCH</span><h2>Build the line.<br>Challenge the edge.</h2><p>A transparent workspace for singles, parlays and player-prop combinations. Every number has a provenance. Every strategy has a gate.</p><a class="button" href="pages/executive-summary.html">Read the executive brief <span>↗</span></a></div><div class="hero-stat"><span>ELIGIBLE FOR COMPETITION</span><strong>00<span>/08</span></strong><p>Evidence incomplete.<br>No strategy promoted on noise.</p><div class="progress"><i></i></div><small>All required gates must PASS.</small></div></div>'
findings=[['Verified foundation','32 standings rows / 256 core fields compared to a fresh NFL.com retrieval.',b('VERIFIED'),a(src[0]['url'])],['Line origination','15 B0 scoring benchmarks; explicitly unvalidated, not market odds.',b('DERIVED'),a(src[0]['url'])],['Skill assessment','No out-of-sample skill evidence. Luck is not removable.',b('BLOCKED'),a(src[8]['url'])],['Current availability','W9 practice report exists; blank game statuses remain blank.',b('VERIFIED'),a(src[3]['url'])]]
page('index','Research overview','An NFL line-origination lab built around traceable evidence—not confident guesses.',hero+kpis+sec('What the evidence says')+table(['Area','Finding','Classification','Source'],findings,'Executive findings')+note('A descriptive relationship is not a betting edge. All eight strategies remain blocked. No verified operator prices, prospective test ledger or bet-leg dependence dataset is available.')+'<div class="section-links"><a href="pages/strategies.html"><strong>Explore the strategy library ↗</strong><p>Singles, joint-event parlays and player opportunities.</p></a><a href="pages/flagged.html"><strong>Review the evidence gaps ↗</strong><p>Corrections, missing values and legacy limitations.</p></a></div>')
# Executive brief
rows=[['Objective','Originate transparent NFL benchmarks and test signal families across singles, parlays and props. Not a claim of profitability.',a(src[0]['url'])],['Verified coverage','32 standings core rows, 15 scheduled matchups, 12 complete score rows, 28 practice entries, 2 news bodies. Coverage only as explicitly listed.',a(src[1]['url'])],['Own lines','B0 averages scoring and opponent concession rates; zero venue adjustment is a design choice. No probabilities inferred from means.',a(src[0]['url'])],['Correlation','Three team-level descriptive estimates; all bet-leg dependence cells blank. Aggregate association cannot price a combo.',a(src[7]['url'])],['Leaderboard','Eight registered research designs; no ranks, performance, badges or rewards awarded. Null is not zero performance.',a(src[8]['url'])],['Validation','PASS-only gates. Missing prices, final availability, chronological holdout or joint-event validation blocks promotion.',a(src[8]['url'])],['Autonomy','Current run needs no user input. Scheduled build/check automation exists; fresh data capture and future grading are not implemented.',a(src[0]['url'])],['Bottom line','No demonstrated skill-based betting edge. Quantify uncertainty rather than promise to eliminate luck.',a(src[8]['url'])]]
page('executive-summary','Executive summary','Decision brief · what is established, what is proposed, and what remains unknown.',table(['Topic','Executive finding','Official reference'],rows,'Executive summary')+sec('Release decision')+note('Publish the research and all gaps. Do not publish actionable selections or reward a strategy until every applicable gate passes. Numerical B0 output is a derived benchmark, not an official NFL fact or validated fair price.'))
# Verified standings
page('standings','Team standings','NFL.com snapshot rechecked on 2026-11-04. Only explicitly confirmed core fields are displayed.',table(['Team','W','L','T','PCT','PF','PA','NET','Streak','Status','Source'],[[r['abbr'],r['W'],r['L'],r['T'],r['PCT'],r['PF'],r['PA'],r['NET'],r['STRK'],b(r['status']),a(r['source_url'])] for r in s['standings']],'Audited standings')+note('HOME/ROAD/DIV/CONF labels and other tail columns were not independently confirmed in this audit and are withheld. Internal arithmetic checks supplement, but do not replace, source inspection.'))
schedule_table=table(['Away','Home/designated','Date','Kickoff (ET)','Network','Venue','Source'],[[g['away'],g['home'],g['date'],g['kickoff_et'],g['network'],None,a(g['source_url'])] for g in s['schedule']],'Week 9 schedule')
score_table=table(['Away','Home','Away score','Home score','Date','Status','Source'],[[g['away'],g['home'],g['away_score'],g['home_score'],g['date'],b(g['status']),a(g['source_url'])] for g in s['scores']],'Week 8 scores')
page('schedule','Schedule & scores','Week 9 matchups and Week 8 results, with incomplete capture values left blank.',schedule_table+sec('Week 8 results')+score_table+note('CIN–ATL is labeled Madrid by the schedule. PIT and TEN are listed on bye. All time labels are Eastern (EST on the W9 injury report); schedule changes remain possible. Venue values not promoted.'))
page('scores','Week 8 scores','Twelve complete score rows observed; two incomplete source captures are intentionally blank.',score_table)
# B0 derived
page('model-lines','Line origination','A reproducible first benchmark—not a validated betting model, fair-price estimate, or recommendation.',note(lines['method'])+table(['Game','Away mean*','Home mean*','Home handicap*','Total*','Market handicap','Edge','Eligible','Input source'],[[g['game'],f"{g['proj_away']:.2f}",f"{g['proj_home']:.2f}",f"{g['home_handicap']:+.2f}",f"{g['model_total']:.2f}",None,None,b('BLOCKED'),a(g['source_url'])+' · '+a(g['inputs_source_url'],'Scoring inputs')] for g in lines['games']],'Derived B0 line benchmarks')+'<p>* Calculated by Own8, not published by the NFL. Negative home handicap means the home team is favored by this unvalidated baseline. Means do not determine win probabilities. Venue, roster, opponent strength, pace and uncertainty adjustments are not fitted.</p>')
page('strategies','Strategy library','Eight research designs. Every strategy is blocked until its applicable evidence gates pass.',table(['ID','Strategy','Category','Testable hypothesis / method','Eligibility','Official metric reference'],[[r['id'],r['name'],r['type'],r['description'],b('BLOCKED'),a(r['source_url'])] for r in strategies],'Strategy registry')+note('These are Own8 research proposals, not official-source strategy recommendations. Test lagged inputs in rolling, pre-kickoff windows. Keep the final season untouched until model and thresholds are frozen.'))
page('correlations','Correlation register','Separate descriptive team association from the event-level dependence needed to price combinations.',table(['Pair','Method','n','r','Confidence interval','Classification','Source'],[[r['pair'],r['type'],r['n'],r['r'],None,b(r['classification']),a(r['source_url'])] for r in corr['correlations']],'Correlation estimates and gaps')+note('The three numerical estimates use 32 season-to-date team aggregates. Teams share games; these are not 32 independent experiments. No IID uncertainty interval, causality, future skill or leg-dependence claim is made.')+sec('Combination research protocol')+'<p>Align legs by game, player, threshold and pregame timestamp. Model the joint distribution, validate calibration on future games, and compare the offered combo price against conservative net expected value. Pairwise correlations do not identify higher-order dependence. Unknown dependence is never treated as independence.</p>')
page('leaderboard','Skill leaderboard','A competition registry, not a fabricated performance ranking. No eligible winner or reward exists.',note(board['note'])+table(['Strategy','Category','Rank','ROI','Brier score','Reward points','Status','Reference'],[[r['name'],r['type'],None,None,None,None,b('BLOCKED'),a(r['source_url'])] for r in board['standings']],'Competition registry')+sec('Proposed reward rule')+'<p>'+e(board['scoring'])+'</p><p>Project design, not an official sporting rule: pre-register eight trials (and count all later variants), use chronological development and an untouched final test, compare proper scores against a fixed baseline, and adjust uncertainty for all trials. Treat CLV as a diagnostic, not proof. No cash rewards, bankroll allocation or wagering are implemented.</p>')
page('validation-gates','Validation gates','Missing, conditional, stale or unverified evidence never counts as PASS.',table(['Gate','Requirement','Current status','Official reference'],[[k,v['rule'],b(v['status']),a(src[8]['url'] if k in ('G3','G6','G7','G8') else src[0]['url'])] for k,v in gates.items()],'Required validation gates')+note('Gate criteria are Own8 design, not NFL or NIST endorsement. Build success means software checks passed—not that a strategy passed evidence gates. Publishing a review flag is allowed; promoting a blocked strategy is not.'))
page('injuries','Availability & news','Practice participation is not game clearance. This is a dated, partial report—not medical advice.',table(['Team','Player','Position','Practice','Injury','Game status','Source'],[[r['team'],r['name'],r['position'],r['practice'],None,None,a(r['source_url'])] for r in s['injuries']],'Week 9 practice report')+note('Other teams display No Injuries Reported in the retrieved page. This is not interpreted as a complete report, health clearance, or final active status. All availability-dependent strategies remain blocked.')+sec('Verified news bodies')+table(['Subject','Reported claim','Publication date','Source'],[[r['subject'],r['claim'],None,a(r['source_url'])] for r in s['news']],'NFL news audit'))
def inventory(rows,caption): return table(['Capture','Row','Inherited label (unverified unless separately audited)','Verified value','Disposition','Official verification target'],[[r['file'],r['row'],r['label'],None,b(r['status']),a(r['source_url'])] for r in rows],caption)
page('player-stats','Data inventory','Every inherited JSON and CSV entry is cataloged. Unsupported values are withheld rather than repeated as facts.',inventory(inv,'Inherited entry inventory')+note('A source URL in an inherited capture is not field-level proof. Labels identify records for review; they are not independently verified player identity or team affiliation. Only audit-snapshot.json fields enter the model.'))
page('team-stats','Team-stat inventory','Only audited standings inputs are used. Other legacy team-stat values are unverified and blank.',inventory([r for r in inv if r['file'].startswith('team-')],'Legacy team-stat entries'))
page('prop-signals','Player-prop research','No verified player game-log, final availability, market quote, or joint-outcome dataset: all prop values blank.',table(['Game','Prop fair line','Market line','Leg correlation','Status','Source'],[[g['game'],None,None,None,b('UNVERIFIED — BLOCKED'),a(g['source_url'])] for g in lines['games']],'Prop evidence gaps'))
method_rows=[['Information cutoff','Freeze data availability timestamps before kickoff; do not use season-ending aggregates to predict earlier games.',a(src[1]['url'])],['Line signs','Predicted home margin = home score − away score. Home handicap = −margin. At a verified market home handicap h, a home cover occurs when realized margin + h > 0 (0 is a push).',a(src[2]['url'])],['Price and EV','Use the operator decimal price d, p(win), p(push): EV per unit = p(win)(d−1) − p(loss). No -110 defaults. Moneyline requires a calibrated distribution, not just a mean.',a(src[8]['url'])],['Correlation','Use aligned bet-event observations, not team means. For two binary events only: P(A∩B)=pa pb + rho sqrt(pa(1−pa)pb(1−pb)), subject to feasible probability bounds. No supplied event estimates, no number.',a(src[7]['url'])],['Generalization','Rolling time splits, lagged features, held-out seasons, calibrated probabilities, comparison to a frozen baseline. Report error and abstention, not only winners.',a(src[8]['url'])],['Multiple testing','Pre-register all variants and test family. Use week/game-block uncertainty and a pre-specified family-wise adjustment; no cherry-picked best backtest.',a(src[9]['url'])],['Prospective settlement','Immutable forecast timestamps, exact operator rules, pushes/voids, prices and units; no settlement without official final outcomes. No forecast ledger currently exists.',a(src[2]['url'])],['Skill uncertainty','Brier=(p−y)^2 and log loss=−log(probability of observed outcome). Reward only a conservative out-of-sample improvement after every evidence gate. No finite test eliminates luck.',a(src[8]['url'])]]
page('methodology','Methodology','Own8 methods and design choices are labeled separately from externally verified facts.',table(['Topic','Project method / requirement','Official context reference'],method_rows,'Research methodology')+note('References support statistical concepts, score inputs, or metric definitions; they do not certify these strategies, chosen gate thresholds, model formulas or rewards.'))
page('repo-review','Repository audit','Line-count and hash inventory of tracked files, with bounded verification—not a blanket factual certification.',note(audit['note'])+table(['File','Lines','SHA-256','Review disposition','Official audit context'],[[r['path'],r['lines'],r['sha256'],r['review'],a(r['source_url'])] for r in audit['files']],'Tracked-file review inventory')+sec('Concurrent sessions')+'<p>Other agents’ independent audit files are preserved in Git. Pending PR #6 and concurrent branches are not merged automatically: their evidence and claims need integration review. The authoritative published surface is this audited dashboard.</p>')
page('sources','Source register','Official pages actually retrieved this session, with exact coverage and limitations.',table(['ID','Official publisher / page','Checked','Supported scope','Source'],[[r['id'],r['label'],r['checked_at'],r['used_for'],a(r['url'])] for r in src],'Official source register')+note('Retrieval used the page-extraction tool; audit-snapshot.json is a structured extract, not retained raw HTTP. Dynamic source pages can change after this audit. External status at release is not guaranteed indefinitely.'))
page('flagged','Flagged for Review','Published, non-blocking review items. Evidence gaps still block strategy promotion.',table(['ID','Priority','Finding / missing evidence','Disposition','Official reference or target'],[[r['id'],r['severity'],r['item'],b('NEEDS REVIEW'),a(r['source_url'])] for r in flags],'Review register')+sec('Inherited entries with unverified values')+inventory([r for r in inv if r['status'].startswith('UNVERIFIED')],'Unverified entry review queue'))
page('responsible-gambling','Responsible research','Paper research only. No wagers, cash prizes, automated bets or profitability guarantees.',table(['Topic','Boundary / resource','Official source'],[['Project boundary','No real-money wagering or cash rewards. No bankroll or stake recommendation.',a(src[-1]['url'])],['Washington resources','Official responsible-gaming and self-exclusion information. We do not make an individual legal eligibility determination.',a(src[-1]['url'])],['Uncertainty','Luck cannot be eliminated. Abstaining is the correct result when evidence is missing.',a(src[8]['url'])]],'Responsible research resources'))
# Redirect legacy docs URL surface rather than serve stale duplicated claims.
for p in (R/'docs').glob('*.html'):
 target='../index.html' if p.stem=='index' else '../pages/'+p.name
 p.write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta http-equiv="refresh" content="0;url='+target+'"><title>Own8 · audited dashboard</title></head><body><p>This historical URL moved to the <a href="'+target+'">audited dashboard</a>.</p></body></html>')
(R/'.nojekyll').write_text('')
print('Built audited root dashboard and category pages; legacy docs redirect.')
